flowchart TD
  start["Início: Ocorrência do vocábulo 'SE'"] --> dec_conjuncao{"A palavra 'SE' liga orações?"}
  dec_conjuncao -- "Sim" --> dec_tipo_conj{"Qual substituição preserva o sentido?"}
  dec_tipo_conj -- "Troca oração por 'ISSO'" --> res_ci["Conjunção Integrante (Oração Substantiva)"]
  dec_tipo_conj -- "Troca por 'CASO'" --> res_cond["Conjunção Subordinativa Condicional"]
  dec_tipo_conj -- "Troca por 'JÁ QUE'" --> res_causal["Conjunção Subordinativa Causal"]
  dec_tipo_conj -- "Troca por 'EMBORA'" --> res_concess["Conjunção Subordinativa Concessiva"]
  dec_conjuncao -- "Não" --> dec_realce{"Pode suprimir o 'SE' sem alteração sintática ou de sentido?"}
  dec_realce -- "Sim" --> res_realce["Partícula de Realce / Expletiva"]
  dec_realce -- "Não" --> proc_pronominal["Etapa 3: Bateria de Testes Pronominais"]
  proc_pronominal --> dec_passiva{"Verbo VTD/VTDI + termo sem preposição? Admite voz passiva analítica?"}
  dec_passiva -- "Sim" --> res_pa["Partícula Apassivadora (PA) — Termo é Sujeito Paciente"]
  dec_passiva -- "Não" --> dec_pis{"Verbo VTI/VI/VL + preposição? Fixo no singular (equivale a 'alguém')?"}
  dec_pis -- "Sim" --> res_pis["Índice de Indeterminação do Sujeito (PIS)"]
  dec_pis -- "Não" --> dec_reflexivo{"Ação recai sobre o sujeito ('a si mesmo') ou é recíproca?"}
  dec_reflexivo -- "Sim" --> res_reflexivo["Pronome Reflexivo / Recíproco (Função OD ou OI)"]
  dec_reflexivo -- "Não" --> dec_piv{"Verbo essencialmente pronominal ou com alteração de regência?"}
  dec_piv -- "Sim" --> res_piv["Pronome Integrante do Verbo (PIV)"]
  dec_piv -- "Não" --> res_outros["Outros Casos / Sujeito Acusativo em Verbos Causativos/Sensitivos"]

flowchart TD
  p1_start["Início: Verbo acompanhado de 'se'"] --> p1_dec_pred{"Qual é a predicação do verbo?"}
  p1_dec_pred -- "VTI, VI ou VL" --> p1_res_pis_vti["PIS / IIS\n(Índice de Indeterminação do Sujeito)"]
  p1_dec_pred -- "VTD ou VTDI" --> p1_dec_prep{"O termo subsequente possui preposição obrigatória?"}
  p1_dec_prep -- "Com preposição (de, em, a)" --> p1_res_pis_prep["PIS / IIS\n(Verbo fixo no singular: 3ª pess. sing.)"]
  p1_dec_prep -- "Sem preposição" --> p1_dec_transp{"Cabe transposição para voz passiva analítica?\n(Sujeito + Ser + Particípio)"}
  p1_dec_transp -- "Sim (conversão válida)" --> p1_res_pa["PA (Partícula Apassivadora)\n(Sujeito Paciente: verbo concorda em número)"]
  p1_dec_transp -- "Não cabe" --> p1_res_outro["Reavaliar Função\n(Pronome Reflexivo / Recíproco / PIV)"]

flowchart TD
  p2_start["Início: Isole a forma verbal acompanhada de pronome"] --> p2_dec_suj{"O sujeito é determinado?\n(ex.: 'A menina', 'Ele')"}
  p2_dec_suj -- "Não" --> p2_res_indet["Teste de PIV Não Aplicável\n(Avaliar PIS/IIS ou Oração Sem Sujeito)"]
  p2_dec_suj -- "Sim" --> p2_proc_flexao["Executar Conjugação Dinâmica:\nEu me... / Tu te... / Ele se... / Nós nos..."]
